    }
    if (set.has(id)) set.delete(id);
    else set.add(id);
    version++;
    console.log(
      `[render] Picked ${layerId} feature #${id} (${set.has(id) ? "selected" : "deselected"}); ${totalSelected()} element(s) selected`
