      filled: true,
      stroked: false,
      getFillColor: (f: PolyFeature) =>
        isSelected("water", f.properties.id)
          ? [...SELECT_COLOR, 230]
          : [...BASE.water, 220],
      pickable: true,
      onClick: (info: PickingInfo) => onClick("water", info),
      onHover: (info: PickingInfo) => onHover("water", info),
      updateTriggers: { getFillColor: version },
